<script>
  (function () {
    var WA_NUMBER = "910000011111";

    function buildMessage(name) {
      return "Hello Thread & Loom, I would like to order: " + name;
    }

    function buildLink(name) {
      return "https://wa.me/" + WA_NUMBER + "?text=" + encodeURIComponent(buildMessage(name));
    }

    function nameFor(slot) {
      var card = slot.closest("[data-product-name]");
      if (card && card.getAttribute("data-product-name")) {
        return card.getAttribute("data-product-name");
      }
      var id = slot.getAttribute("data-product-id");
      var list = window.J2_PRODUCTS || [];
      for (var i = 0; i < list.length; i++) {
        if (list[i].id === id) return list[i].name;
      }
      return "";
    }

    function addButtons() {
      var slots = document.querySelectorAll(".w2-order-slot[data-product-id]");
      for (var i = 0; i < slots.length; i++) {
        var slot = slots[i];
        if (slot.querySelector(".w3-order")) continue;
        var name = nameFor(slot);
        if (!name) continue;
        var a = document.createElement("a");
        a.className = "j2-btn w3-order";
        a.href = buildLink(name);
        a.target = "_blank";
        a.rel = "noopener noreferrer";
        a.setAttribute("aria-label", "Order " + name + " on WhatsApp");
        a.textContent = "Order on WhatsApp";
        slot.appendChild(a);
      }
    }

    window.J2_buildWhatsAppLink = buildLink;

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", addButtons);
    } else {
      addButtons();
    }
  })();
</script>
